using TomasAI.IFM.Shared.EventSourcing;
using TomasAI.IFM.Domain.Trade.Futures.Position.Model;using TomasAI.IFM.Domain.Trade.Futures.Option.Position.VerticalSpread.Command.State;using TomasAI.IFM.Domain.Trade.Shared.Futures.Option.Position;using TomasAI.IFM.Domain.Trade.Shared.Model;using TomasAI.IFM.Domain.Trade.Model;using TomasAI.IFM.Shared.Domain;
namespace TomasAI.IFM.Domain.Trade.Futures.Option.Position.VerticalSpread.Command.Extensions;
public static class VerticalSpreadPositionCommandHandlers{public static ServiceResult<GuidResult>Execute(this OpenVerticalSpreadPositionCommand c,VerticalSpreadPositionCommandState s)=>Apply(c,s,m=>m.Open(c.Trade,c.EntityId.PositionId,c.EffectiveAtUtc));public static ServiceResult<GuidResult>Execute(this UpdateVerticalSpreadPositionLegMarketPriceCommand c,VerticalSpreadPositionCommandState s)=>Apply(c,s,m=>m.UpdateLeg(c.TradeLegId,c.Price,c.SourceSequence,c.EffectiveAtUtc,c.RouteGeneration));public static ServiceResult<GuidResult>Execute(this EndOfDayVerticalSpreadPositionCommand c,VerticalSpreadPositionCommandState s)=>Apply(c,s,m=>m.EndOfDay(c.EffectiveAtUtc));public static ServiceResult<GuidResult>Execute(this CloseVerticalSpreadPositionCommand c,VerticalSpreadPositionCommandState s)=>Apply(c,s,m=>m.Close(c.EffectiveAtUtc));public static ServiceResult<GuidResult>Execute(this CorrectVerticalSpreadPositionBasisCommand c,VerticalSpreadPositionCommandState s)=>Apply(c,s,m=>m.CorrectBasis(c.TradeLegId,c.Price,c.EffectiveAtUtc));public static ServiceResult<GuidResult>Execute(this SnapshotVerticalSpreadPositionCommand c,VerticalSpreadPositionCommandState s)=>s.Current is{}?TradeCommandResult.Accepted(c.CommandId):new ServiceFailed<GuidResult>(c.ErrorCode,"POSITION.NOT_FOUND");static ServiceResult<GuidResult>Apply(PositionCommand c,VerticalSpreadPositionCommandState s,Func<StrategyPositionActorStateMachine,TradeDecision<StrategyPositionSnapshot>>f){var m=new StrategyPositionActorStateMachine();if(s.Current is{}x)m.Replay(x);var d=f(m);if(!d.Accepted||d.Value is null)return TradeCommandResult.Rejected(c.ErrorCode,d);s.Update(new VerticalSpreadPositionChangedEvent{EntityId=c.EntityId,State=d.Value},c);return TradeCommandResult.Accepted(c.CommandId);}}
